<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\User\Domain\ValueObject;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class UserEmailVerifiedVO
{
    public static function empty(): UserEmailVerifiedVO
    {
        return new UserEmailVerifiedVO(null);
    }
    public static function from(UserEmailVerifiedVO|bool|null $value): UserEmailVerifiedVO
    {
        return self::fromUnsafe($value);
    }
    public static function tryFrom(mixed $value, ConstraintFailList $list): ?UserEmailVerifiedVO
    {
        if ($value instanceof UserEmailVerifiedVO) {
            // If is a ValueObject, its already validated... nothing to append
            return $value;
        } elseif (!$value) {
            return new UserEmailVerifiedVO($value);
        } elseif (is_bool($value)) {
            return new UserEmailVerifiedVO($value);
        } else {
            $list->add(new ConstraintFail('wrong_type', ['emailVerified'], [$value], ['bool']));
            return null;
        }
    }
    private static function fromUnsafe(mixed $value): UserEmailVerifiedVO
    {
        if ($value instanceof UserEmailVerifiedVO) {
            // If is a ValueObject, its already validated
            return $value;
        } else {
            // If is not a ValueObject, validation is need and exception throw
            $errorsList = new ConstraintFailList();
            $candidate = self::tryFrom($value, $errorsList);
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            \assert($candidate instanceof UserEmailVerifiedVO);
            return $candidate;
        }
    }
    /**
     * private constructor to avoid build a value without all the rule validations.
     */
    private function __construct(
        private readonly ?bool $emailVerified
    ) {
    }
    public function value(): ?bool
    {
        return $this->emailVerified;
    }
    public function equals(?UserEmailVerifiedVO $other): bool
    {
        return $this->value() == $other?->value();
    }
}
